INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:25:02.707661+09',348,'019bae84-e173-7aa4-b97b-82af882787b1'::uuid,'2122년, 2천만톤의 광물과 7명의 승무원을 태우고 지구로 귀환중인 화물선 노스트로모호의 메인 컴퓨터 마더는 어떤 위성에서 나오는 알 수 없는 신호를 포착하게 된다. 마더에 의해 동면중 깨어난 승무원들은 이 신호를 조사하기 위해 혹성 LA-426에 착륙한다. 이들 중엔 2등 항해사인 엘렌 리플리도 있다. 혹성에서 정체 불명의 우주선을 발견한 그들은 탐사에 나서지만, 우주선은 이미 오래전에 파괴되어 썩고 있었으며 승무원들은 모두 미이라로 변해 있다. 사고 원인을 찾기 위해 좀 더 안으로 들어간 조사반은 여기저기 계란 모양의 물체가 있는 산란실을 발견하는데...','/k3m1RdlYUlCx51PxxNMlmbm7QSk.jpg','에이리언','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.707675+09',260446,'019bae84-e173-7ade-b97c-2eca167287cf'::uuid,'','/lxbEw2xrtF8DyntLV1fliV1e6to.jpg','La fine è nota','MOVIE'),
