INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:25:02.710106+09',385687,'019bae84-e176-71c5-b725-5cfd58fde74d'::uuid,'돔과 그의 패밀리 앞에 나타난 운명의 적 단테. 과거의 그림자는 돔의 모든 것을 파괴하기 위해 달려온다. 단테에 의해 산산히 흩어진 패밀리들은 모두 목숨을 걸고 맞서야 하는 함정에 빠지고 마는데...','/cltj9nKLzl0HXtz2qdu55BoIgOn.jpg','분노의 질주: 라이드 오어 다이','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.71013+09',70292,'019bae84-e176-7228-b726-4cf342ef7df4'::uuid,'','/KMMN2tmgyxE6o4evtwbqXTTt4q.jpg','En häxa i familjen','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710145+09',55960,'019bae84-e176-7262-b727-b4bde82bf64d'::uuid,'','/jHe65nUmr2DBuzEAAkuiFbUssYT.jpg','Totò, Peppino e la... malafemmina','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.71016+09',1495694,'019bae84-e176-72a2-b728-1ec28476f92c'::uuid,'참담한 이별을 겪은 후, 한 음악 지망생이 호주로 도피한다. 그녀는 억만장자 와인 제조업자와 조건 없는 연애를 하기로 동의하지만, 사랑에 빠지게 되자 떠나야 할지, 사랑을 두려워하는 남자에게 마음을 걸어야 할지 선택해야 한다.','/mJtBKvHQaFzgp0N6JFskSvjbTar.jpg','뷰티 프롬 페인','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:13.684182+09',64041,'019bae85-0c54-72f8-812c-db6ef3b1eb16'::uuid,'','/oIOTNJN0SSYdpem7iQFUgUrqpfW.jpg','Totò a Parigi','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710233+09',1241742,'019bae84-e176-73ca-b72d-9412b97973f1'::uuid,'세 가지 인생, 세 가지 강렬한 자극! 인생에 단 한 번 만나게 되는 에로틱 트릴로지','/gcK3HgN6IHNOviXnX11W6aFLTGv.jpg','엑스: 세 개의 이야기','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710248+09',671,'019bae84-e176-740a-b72e-7d56066d1929'::uuid,'해리 포터는 위압적인 버논 숙부와 냉담한 이모 페투니아, 욕심 많고 버릇없는 사촌 더즐리 밑에서 갖은 구박을 견디며 계단 밑 벽장에서 생활한다. 이모네 식구들 역시 해리와의 동거가 불편하기는 마찬가지. 이모 페투니아에겐 해리가 이상한 언니 부부에 관한 기억을 떠올리게 만드는 달갑지 않은 존재다. 11살 생일이 며칠 앞으로 다가왔지만 한번도 생일파티를 치르거나 제대로 된 생일선물을 받아 본 적이 없는 해리로서는 특별히 신날 것도 기대 할 것도 없다. 11살 생일을 며칠 앞둔 어느 날 해리에게 초록색 잉크로 쓰여진 한 통의 편지가 배달된다. 그 편지의 내용은 다름 아닌 해리의 11살 생일을 맞이하여 호그와트에서 보낸 입학 초대장이었다. 그리고 해리의 생일을 축하하러 온 거인 해그리드는 해리가 모르고 있었던 해리의 진정한 정체를 알려주는데...','/8YaP48tVfngbURGldWk1I5odsBK.jpg','해리 포터와 마법사의 돌','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710264+09',672,'019bae84-e176-7449-b72f-f57cc47378b4'::uuid,'해리 포터에겐 이번 여름방학이 별로 즐겁질 못했다. 마법이라면 질색을 하는 페투니아 이모와 버논 이모부의 구박도 그렇지만, 무엇보다 속상한 건 단짝이었던 론 위즐리와 헤르미온느 그레인저가 그 사이 자신을 까맣게 잊었는지 자신의 편지에 답장 한 통 없다는 것.  그러던 어느날 꼬마 집요정 도비가 해리의 침실에 나타나 뜻밖의 얘기를 한다. 호그와트 마법학교로 돌아가면 무서운 일을 당할 거라는 것. 도비는 해리를 학교에 못 가게 하려고 자신이 여태까지 론과 헤르미온느의 답장을 가로채 왔음을 고백한다. 그러나 도비와 더즐리 가족의 방해에도 불구, 해리는 론과 그의 형제들이 타고 온 하늘을 나는 자동차를 타고 이모집을 탈출, 따뜻한 가족애가 넘치는 론의 집으로 가는데...','/bo8FuQPWKLqbg3WgAXYISkwrbZ9.jpg','해리 포터와 비밀의 방','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710278+09',673,'019bae84-e176-7484-b730-7a249cd67954'::uuid,'13세가 된 해리 포터는 또 한번의 여름 방학을 이모 가족인 더즐리 일가와 우울하게 보내야 했다. 물론 마법을 쓰는 건 일체 금지. 하지만, 버논 이모부의 누이인 마지 아줌마가 더즐리 가를 방문하면서 상황은 변한다. 위압적인 마지는 해리에겐 늘 공포의 대상. 마지 아줌마 때문에 스트레스를 받던 해리는 급기야 실수로 그녀를 거대한 괴물 풍선으로 만들어 하늘 높이 띄워 보내버리고 만다. 이모와 이모부에게 벌을 받을 것도 두렵고, 일반 세상에선 마법 사용이 금지돼 있는 것을 어겼기 때문에 호그와트 마법학교와 마법부의 징계가 걱정된 해리는 밤의 어둠 속으로 도망치지만, 순식간에 근사한 보라색 3층 버스에 태워져 한 술집으로 인도되고 마는데...','/anwNl1xbzXoj5Ax1nVw3WoDzHlw.jpg','해리 포터와 아즈카반의 죄수','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710292+09',1295026,'019bae84-e176-74bd-b731-3d0d328f9892'::uuid,'선천적으로 발이 빨라 달리기에서 지는 법이 없던 토가시는 현실을 잊기 위해 무작정 달렸던 전학생 코미야를 만나 제대로 달리는 법을 가르쳐 준다. 누구보다 빠르게 달릴 때의 환희를 알게 된 코미야는 토가시에게 100M 경주를 신청하고 그날의 경기 이후 코미야는 토가시의 앞에서 사라진다. 그리고 몇 년 후, 계속 이겨야 한다는 압박감에 시달리고 있던 토가시 앞에 일본 기록 경신을 꿈꾸는 코미야가 나타나는데…','/itooVuz3gka7ykr3TpOvwXYqESM.jpg','100미터.','MOVIE');
INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:25:02.710307+09',674,'019bae84-e176-74fc-b732-9ab326c9dd8e'::uuid,'요즘 들어 매일 꾸는 악몽 때문에 이마의 상처에 더욱 통증을 느끼는 해리는 친구 론과 헤르미온느와 함께 퀴디치 월드컵에 참가해 악몽에서 벗어날 수 있게 돼 마냥 기쁘다. 그러나 퀴디치 캠프장 근방 하늘에 불길한 기운이 나타난다. 바로 마왕 볼드모트의 상징인 어둠의 표식이 나타난 것. 볼드모트가 13년 전에 자취를 감춘 뒤, 감히 모습을 드러내지 못했던 그의 추종자 데스 이터들이 그 표식을 불러낸 것이다. 두려움으로 가득 찬 해리는 안전한 호그와트 마법학교로 돌아가고 싶어한다. 덤블도어 교장이라면 자신을 지켜줄 수 있을 것이기에. 그러나 올해는 예년과 상황이 좀 다른데...','/uWPnKtu1eutmgBQ2hoWm0Xe8nfN.jpg','해리 포터와 불의 잔','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710321+09',675,'019bae84-e176-7536-b733-447ff73748ab'::uuid,'길고도 지루한 여름 날 호그와트 마법학교 다섯 번째 해를 기다리고 있는 해리포터. 이모부 더즐리 식구들과 참고 사는 것도 지겨운데다 친구 론과 헤르미온느에게서는 편지 한 통 오지 않는다. 그러던 중 예상치 못했던 편지 한 장이 도착한다. 그것은 해리가 학교 밖인 리틀 위닝에서 얄미운 사촌 두들리, 즉 머글 앞에서 디멘터들의 공격을 막는 마법을 사용했기 때문에 호그와트 마법학교에서 퇴학 당하게 되었다는 소식이었다. 앞이 캄캄한 해리. 갑자기 어둠의 마법사 오러들이 나타나 해리를 불사조 기사단의 비밀 장소로 데리고 가는데...','/1ItejykqHTbFWbZXdzqlvqriv7K.jpg','해리 포터와 불사조 기사단','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710336+09',756397,'019bae84-e176-7570-b734-bfd5cc958bff'::uuid,'','/bYa20LYAZ3Q7lKXtLYybo0yWWTN.jpg','Hitpig!','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.71035+09',680,'019bae84-e176-75aa-b735-391d36efab6e'::uuid,'펌프킨와 허니 버니가 레스토랑에서 강도 행각을 벌이기 시작한다. 빈센트와 그 동료 쥴스는 두목의 금가방을 찾기 위해 다른 건달이 사는 아파트를 찾아간다. 마르셀러스는 부치에게 돈을 주며 상대 선수에게 져 주라고 하지만 부치는 상대 선수를 때려 눕히고 도망치다, 어릴 때 아버지에게 물려받은 시계를 찾기 위해 아파트로 향한다. 아무런 상관 없이 보이는 이 사건들이 서로 얽히고 섥히면서 예상치 못한 인과관계가 만들어지는데...','/6lXRHGoEbnnBUKsuqpL9JxD4DzT.jpg','펄프 픽션','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710365+09',694945,'019bae84-e176-75e9-b736-fa99cf7a1086'::uuid,'','/j7SAGtw8RtcgLXFMhrWNR28mqqv.jpg','Bad Boy Made Good: The Revival of George Antheil''s 1924 Ballet Mécanique','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710379+09',51885,'019bae84-e176-7623-b737-240de036c36b'::uuid,'제작 기간만 3년이 걸린 배우 겸 감독 지앙원의 오랜 기대작. 각각 다르지만 네 개의 서로 연관되어 있는 네 개의 이야기를 통해 지앙원은 사랑과 불륜, 결혼과 탄생, 열정과 오해, 기억과 꿈, 모자 관계 등 때로는 해석하기 어려운 삶 그 자체를 이야기하고 있다.','/jlcclHDPbyEoZDCcHYQ9SDo0fRf.jpg','태양은 다시 떠오른다','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710393+09',340648,'019bae84-e176-765d-b738-004710f26d9f'::uuid,'','/zB6rpbIcxHGNj9XYsjozIahTDIU.jpg','莎莎嘉嘉站起來','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.71075+09',375548,'019bae84-e176-7c13-b750-f338d84b0cf4'::uuid,'','/eKsPXxODoYh8xwC7fnmHjZL61au.jpg','Uno al año no hace daño','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710775+09',62201,'019bae84-e176-7c77-b751-fb2bfe1d527b'::uuid,'','/2ZUpj73MzEh2YwVzJNVUqBSu2LZ.jpg','शहँशाह','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710799+09',299775,'019bae84-e176-7ce0-b752-773092ba2d07'::uuid,'','/oH1BvRZL2K6PJi9dfc1XzH83eFc.jpg','Der Kaiser und das Wäschermädel','MOVIE');
INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:25:02.71041+09',617126,'019bae84-e176-76a1-b739-ed92854213f7'::uuid,'1960년대, 전 세계적인 관심 속 우주로 떠난 4명의 엘리트 우주비행사 ‘리드 리처드’, ‘수잔 스톰’, ‘조니 스톰’, ‘벤 그림’은 예기치 못한 사고로 우주 방사능에 노출되면서 초인적인 능력을 갖게 된다. 신체를 자유자재로 변형할 수 있게 된 ‘리드 리처드’(미스터 판타스틱)부터 온몸이 투명해지고, 강력한 방어막을 형성하는 ‘수잔 스톰’(인비저블 우먼), 온몸으로 뜨거운 화염을 내뿜으며 비행 능력까지 지닌 ‘조니 스톰’(휴먼 토치), 그리고 바위 같은 엄청난 피지컬과 압도적 파워를 갖춘 ‘벤 그림’(씽)까지 ‘판타스틱4’라는 새로운 슈퍼 히어로 팀이 된 4명의 멤버들. 인생에 완전히 새로운 국면을 맞이하게 되면서 혼란과 갈등에 휩싸인 이들 앞에 행성 파괴자 ‘갤럭투스’의 위협을 전달하는 미스터리한 전령 ‘실버서퍼’가 등장해 지구 파괴를 예고하고 ‘판타스틱 4’는 세상을 구하기 위해 다 함께 힘을 모으게 되는데…','/sHgIQvDlk5188wo9jM8IKFeyJUd.jpg','판타스틱 4: 새로운 출발','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710424+09',291508,'019bae84-e176-76db-b73a-efccacd884df'::uuid,'','/tQttBvMIYVq6MuXfrOHGCjy0pBN.jpg','Es flüstert die Liebe','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710438+09',957119,'019bae84-e176-7715-b73b-e456a819d52e'::uuid,'','/mSL6truNrWP1Bn9ng1rN0SkMI4f.jpg','Sidelined: The QB and Me','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710454+09',682672,'019bae84-e176-7753-b73c-e0f0168b59e3'::uuid,'','/cEGex7yrWerQgBsonJodDJZAttV.jpg','Jeff Allen: Honor Thy Wife','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710468+09',103099,'019bae84-e176-778d-b73d-d59f4871b858'::uuid,'','/2NV7RXexsEdJZOAmiiwAfIk0Cr6.jpg','A Tale of Egypt','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710482+09',303813,'019bae84-e176-77c6-b73e-3079e37e5d07'::uuid,'','/uUFM5hvyeplaY6I7eQSh6rI2GMO.jpg','Por Dúvida das Vias','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710498+09',66245,'019bae84-e176-7808-b73f-40ef49e6cac9'::uuid,'','/vplqDhbUk5GMPUosMuQy91NePxv.jpg','அருணாச்சலம்','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710513+09',2757,'019bae84-e176-7848-b740-5e5ea0a4cc46'::uuid,'LA의 무능한 시나리오 작가 찰리 카우프만은 기승전결도, 확실한 사건의 전개도 없는 소설의 각색에 고심하고 있다. 그에게 시나리오 작가가 되겠다며 찰리를 찾아온 쌍둥이 동생 도널드는 또 다른 골칫거리다. ‘난초 도둑’과 도널드라는 두 가지 고민을 안고 있던 찰리는 결국 도널드의 충고대로 뉴욕에 살고 있는 소설의 원작자 수잔 올리언을 찾아간다. 이렇게 그가 수잔 올리언의 <난초 도둑>을 각색하기 위해 고군분투하는 동안 카우프만의 삶은 한심함에서 기괴함으로 변해 가고, 카우프만과 올리언의 책 속 인물들의 삶은 서로 충돌하면서 기묘하게 얽히게 되는데...','/mi4sFNf7wVdnzhR3NYprSOQpBXR.jpg','어댑테이션','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710527+09',1104601,'019bae84-e176-7881-b741-3a3829d7d712'::uuid,'','/3YjCBoucA8vQ6MI9GpdGCdfGaXP.jpg','Dnevnik Pauline P.','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710541+09',424649,'019bae84-e176-78bb-b742-ebb2b963cc12'::uuid,'','/6Kf49vsaVDdxcXavEeDrulRsrbD.jpg','Model for Murder: The Centerfold Killer','MOVIE');
INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:25:02.710557+09',1389255,'019bae84-e176-78fa-b743-1e76b43cd2b9'::uuid,'','/8rxFUdvtFwAxbyZfSBKPB2Vaal9.jpg','The Stranger in My Home','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710571+09',445141,'019bae84-e176-7934-b744-eae6d70e5605'::uuid,'','/yCFUrfORclz4I2ErmaiMgREXlaD.jpg','Lojze se je zbudil tako, kot po navadi','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710585+09',410323,'019bae84-e176-796d-b745-feaddca9042f'::uuid,'','/2aCk4sPBY9IlWFctXFw4LEtf7lz.jpg','நெருப்புடா','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.7106+09',1252037,'019bae84-e176-79ab-b746-05d447ed52d0'::uuid,'1943년 동부 전선. 독일군 티거 전차 분대는 치열한 최전선 너머로 침투해야 하는 위험한 임무를 맡는다. 그들은 생사를 장담할 수 없는 무인 지대를 헤쳐 나가며 적과 내면의 악마를 동시에 마주해야 한다.','/swNuqlHua7uLgV6ulS4t2RGP2sd.jpg','전차 티거','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710614+09',312019,'019bae84-e176-79e5-b747-c19a390b210f'::uuid,'','/lnwtXqgamZdMd9Gm8HbCxRULpJg.jpg','Die große und die kleine Welt','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710628+09',637649,'019bae84-e176-7a1f-b748-2c33100db86e'::uuid,'캐시트럭을 노리는 무장 강도에 의해 아들을 잃은 H(제이슨 스타뎀). 분노에 휩싸인 그는 아들을 죽인 범인의 단서를 찾기 위해 현금 호송 회사에 위장 취업한다. 첫 임무부터 백발백중 사격 실력을 자랑하며, 단숨에 에이스로 급부상한 H. 캐시트럭을 노리는 자들을 하나 둘 처리하며, 아들을 죽인 범인들과 점점 가까워지는데… 자비는 없다, 분노에 가득 찬 응징만이 남았다.','/qEkQy6H83Sz7vPWN9ZQXWl9RiBF.jpg','캐시트럭','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710642+09',49884,'019bae84-e176-7a59-b749-fc1396ba314e'::uuid,'','/uIEijZEjVwAXQ2ItBdWpBPor3yi.jpg','Sinterklaasjournaal: De Meezing Moevie','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710658+09',271077,'019bae84-e176-7a98-b74a-04501a1dbf18'::uuid,'','/ksjOh0vMk70RHpT5wHtiewnrDxy.jpg','Língua - Vidas em Português','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710672+09',10977,'019bae84-e176-7ad1-b74b-c7d43cc8dab2'::uuid,'','/zQTyFuNYJWr6Lu2VFZKxWwCG2sj.jpg','Zur Hölle mit den Paukern','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710686+09',1327862,'019bae84-e176-7b0a-b74c-770c501d9a19'::uuid,'여자친구가 있는 학교 인기남 ‘밀러’를 좋아하는 고등학생 ‘클라라’는 자신을 과잉보호하는 엄마 ‘모건’ 대신 이모 ‘제니’에게 의지하며 연애 상담을 이어간다. 그러던 어느날, ‘클라라’가 가장 좋아하는 제니와 아빠 ‘크리스’가 같은 날 사고로 세상을 떠나게 되고 모건과 제니의 약혼자 ‘조나’는 둘 사이의 충격적 비밀을 알게되어 분개한다. ‘모건’과 ‘조나’는 충격받을 ‘클라라’를 위해 이 사실을 숨기면서도 분노를 참을 수 없어 떠난 두 사람의 흔적을 지우려고만 하고 그로 인해 상심한 ‘클라라’를 ‘밀러’가 위로하면서 둘은 서로 가까워지게 되는데…','/jJinKJWCTAwMPTcvTq5eH2yBc8w.jpg','리그레팅 유','MOVIE');
INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:25:02.710701+09',436969,'019bae84-e176-7b49-b74d-ef1f18fafe3d'::uuid,'최고의 사망률을 자랑하는 벨 리브 교도소. 미국 정보국 월러 국장은 태스크 포스 X라는 극비 군사 작전팀을 꾸리기 위해 이곳에 왔다. 그녀는 수감 중인 슈퍼 빌런들을 팀에 합류시키기 위해 사면이나 감형을 조건으로 제시한다. 또한 만약을 대비해 언제라도 이들을 처형할 수 있게 머리에 폭탄도 심어놓는다. 우여곡절 끝에 완성된 팀은 두개로 나뉘어 남미의 작은 섬나라 코르토 몰티즈로 향한다. 이들의 임무는 이 섬에 위치한 요툰하임이라는 비밀 연구실에 잠입해 스타피쉬의 흔적을 없애는 것. 각기 다른 해안가에 도착한 두 팀은 상반된 상황을 맞이한다.','/1FiLuxuowOusZAG1vvI4TorMuNG.jpg','더 수어사이드 스쿼드','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710719+09',103150,'019bae84-e176-7b93-b74e-440dfa1115ff'::uuid,'','/bgqVOdqEDsFntQANN1lJ5SrWftH.jpg','Gitana tenías que ser','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710735+09',387824,'019bae84-e176-7bd3-b74f-9171e91f4a8f'::uuid,'“엄마한테 이런 친구도 있었어?!”  파란만장하고 판타스틱한 대학생활을 꿈꾸던 스무살 성수. 하지만 상경하자마자 부동산 사기를 당하고 만다. 얼떨결에 엄마 손에 이끌려 엄마친구 자영의 집에 얹혀 살게 된 성수는 자영을 보는 순간 믿을 수 없는 초절정 동안과 섹시한 바디 라인에 빠져 들고 만다. 매일 마주치는 자영을 보며 그녀를 향한 은밀한 상상이 점점 도를 넘는 수준에 이르던 성수는 어느 날, 그녀가 은밀하게 숨겨온 놀랍고도 화끈한 비밀을 알게 되는데...','/eLEqhVjleFUgxYWtgIgZ0gHdi3o.jpg','엄마친구','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710831+09',264955,'019bae84-e176-7d5f-b754-6da1f06de871'::uuid,'','/8DcRDOCuIjmIi56AIy3tliTSbTz.jpg','Wo der Wildbach durch das Höschen rauscht - Witwen-Report','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710846+09',767,'019bae84-e176-7d99-b755-6cfe1cc2293c'::uuid,'어둠의 세력이 더욱 강력해져 머글 세계와 호그와트까지 위협해온다. 위험한 기운을 감지한 덤블도어 교수는 다가올 전투에 대비하기 위해 해리 포터와 함께 대장정의 길을 나선다. 볼드모트를 물리칠 수 있는 유일한 단서이자 그의 영혼을 나누어 놓은 7개의 호크룩스를 파괴하는 미션을 수행해야만 하는 것! 또한 덤블도어 교수는 호크룩스를 찾는 기억여행에 결정적 도움을 줄 슬러그혼 교수를 호그와트로 초청한다. 한편 학교에서는 계속된 수업과 함께 로맨스의 기운도 무르익는다. 해리는 자신도 모르게 지니에게 점점 끌리게 되고, 새로운 여자 친구가 생긴 론에게 헤르미온느는 묘한 질투심을 느끼는데...','/yrGlb3HLtjGp39mv4MJ5UuIHcj4.jpg','해리 포터와 혼혈왕자','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.71086+09',769,'019bae84-e176-7dd2-b756-4785772c3402'::uuid,'아일랜드계 이탈리아인 헨리 힐와 토미는 13살에 마피아에 입문해 지미와 함께 트럭이나 공항 화물을 훔치는 일을 한다. 결혼 후에도 마피아 생활을 계속하는 헨리는 이제 조직에서도 안정된 위치와 경제적 여유를 갖는다.  어느 날 헨리와 지미는 공항터미널 사건을 모의해 현금 6백만 달러라는 엄청한 돈을 훔친다. 이 사건을 은폐하기 위해 혈안이 된 지미는 모의에 참여했던 사람들을 죽이고, 토미는 마피아 조직에 가담했다가 살해당한다. 엎친데 덮친격으로 헨리마저 마약거래로 경찰서에 잡혀 들어가는데...','/zF9hSBS1t7PVFLo01GrJ3OjGi67.jpg','좋은 친구들','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710875+09',772,'019bae84-e176-7e12-b757-bb7416d61dae'::uuid,'시카고에 살고 있는 케빈의 가족은 크리스마스에 플로리다에 가기로 되어있다. 그러나 공항의 소란 속에, 홀로 뉴욕행 비행기에 오르게 되어 거대한 도시에 혼자 남게 된 케빈은 기지를 발휘하여 아버지 카드로 플로리자 호텔에 묶게되고, 의심스러워 하는 종업원들을 멋지게 따돌린다. 한편, 감옥을 탈출한 2인조 강도 마브와 해리는 뉴욕의 장난감 가게를 털어 한 몫 잡을 꿈에 부풀어 있는데...','/8lxJrcl24SWRAbLxOJNsvgFlSGa.jpg','나 홀로 집에 2: 뉴욕을 헤매다','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710889+09',1422096,'019bae84-e176-7e4d-b758-e17147993a7a'::uuid,'인간 친구 토드가 며칠 전부터 이상하다. 여기서 토드를 지킬 수 있는 건 나 밖에 없다. 우리의 세계가 무너지지 않도록 내가 나서야 한다.','/t4HhBZDq9Wjxrm1iKZOwZnyJPFy.jpg','굿 보이','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710904+09',8966,'019bae84-e176-7e86-b759-45269c7745ec'::uuid,'17세의 평범한 고등학생 소녀 ‘벨라’는 집안 사정으로 워싱턴 주 포크스에 있는 아빠의 집으로 이사를 온다. 전학 첫날, ‘벨라’는 냉담하지만 자신을 무장 해제시킬 정도로 잘생긴 ‘에드워드’와 마주치고, 전율과 두려움 넘치는 인생의 전환을 맞이한다. ‘에드워드’와 돌이킬 수 없는 사랑에 빠져든 ‘벨라’. 하지만 ‘에드워드’와 그의 가족이 뱀파이어 일족이라는 사실을 알게 되고, 예기치 못한 운명에 빠져든다.','/ryvt6cLTjHHH7Nnce3Xi5S3I533.jpg','트와일라잇','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710919+09',11016,'019bae84-e176-7ec6-b75a-e34f1845d31f'::uuid,'21회 아카데미 여우조연상(클레이어 트레보어) 수상.  의협심 강한 프랑크 맥클라우드 소령은 예편 후 동료 전우의 가족을 방문하기 위해 ''키 라르고''섬을 찾는다. 하지만 그를 복병처럼 그를 기다리고 있었던 것은 무시무시한 태풍과, 위조화폐 거래를 위해 밀입국해서 호텔을 전세내 투숙하고 있던 마피아 로코 일당. 밖에선 태풍이 몰아치는 가운데 가족과 인질로 잡힌 맥클라우드는 기회주의적이고 야비한 로코와 한바탕 심리전을 펼친다. 결국 탈옥했던 인디언 두 명과 경찰 한 명이 살해되고 태풍은 지나가나 짧은 안도의 순간처럼 맥클라우드와 친구의 부인 노라의 애정을 확인하자마자 맥클라우드는 로코 일당을 태우고 쿠바로 끌려가게 된다. 태풍이 지나간 뒤의 적막처럼 이별을 아쉬워하며 섬엔 적막이 감도는 가운데 배를 몰고 쿠바로 향하던 맥클라우드는 지금껏 보여준 온유한 태도를 버리고 로코의 정부 게이가 준 총으로 매섭게 인간 쓰레기를 청소하고 키 라르고 섬으로 돌아간다.','/rySfmQQZhS7RswOiJcJrww6FcHy.jpg','키 라르고','MOVIE');
INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:25:02.710933+09',82702,'019bae84-e176-7f00-b75b-378d2e55a9df'::uuid,'바이킹과 드래곤이 친구가 되어 평화롭게 살아가는 버크섬.  청년이 된 히컵은 아버지 스토이크의 바람과는 달리  족장이 되는 것 보다 버크섬 밖의 더 넓은 세상을 보고 싶어한다.  그러던 어느 날, 신비로운 얼음대륙을 탐험하던 히컵과 투슬리스는 드래곤 사냥꾼들이 쳐놓은 덫에 걸리고,  드래곤들을 위협하는 강력한 어둠의 존재에 대해 알게 된다.  히컵과 투슬리스는 드래곤들의 평화를 위해  의문의 드래곤 군단과 맞서기로 결심하는데…','/kSP4QmHMLnbySksUb2O9sGkoEQM.jpg','드래곤 길들이기 2','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710947+09',211729,'019bae84-e176-7f3a-b75c-be7e184be441'::uuid,'','/cxv8MRnpAhd4izS0yHHeQPgn6FR.jpg','Freeway','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710962+09',453395,'019bae84-e176-7f74-b75d-905173abafbc'::uuid,'아메리카는 어느 날 멀티버스 사이를 오갈 수 있는 힘에 눈을 뜨지만 완전히 제어하지 못한다. 정체불명의 악마가 아메리카를 죽이려 하자 다른 우주의 스트레인지가 이를 막아보지만 결국 살해당한다. 우여곡절 끝에 우리가 알고 있는 우주로 넘어온 아메리카는 어벤져스 멤버인 닥터 스트레인지의 도움과 보호를 받는다. 닥터 스트레인지는 웨스트뷰 사건 이후 잠적한 완다에게 도움을 청하지만 곧바로 그녀가 사건의 진정한 흑막, 스칼렛 위치임이 드러난다. 스칼렛 위치는 자신의 원하는 멀티버스로 가기 위해 아메리카의 힘을 흡수하려 한다. 닥터 스트레인지와 아메리카는 압도적인 힘을 지닌 스칼렛 위치를 피해 또 한번 다른 멀티버스로 도망치지만 그의 끈질긴 추격을 받는다.','/vL5ktZauR0fZMDOHKjakb1idhuU.jpg','닥터 스트레인지: 대혼돈의 멀티버스','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710977+09',1078023,'019bae84-e176-7fb4-b75e-3a6e7272ba76'::uuid,'','/r5C85R0Bc6RL51PnPv2HIvpSMJ7.jpg','저격지왕: 암살','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.710991+09',293660,'019bae84-e176-7fee-b75f-c6506fad8495'::uuid,'특수부대 요원 출신의 용병 웨이드 윌슨은 취향과 장난기마저 똑 닮은 바네사를 만나 행복한 나날을 보낸다. 하지만 행복은 광고처럼 짧은 법. 말기 암 선고를 받은 웨이드는 비밀 임상실험에 참여하며 재기를 노린다. 극한의 고문으로 이뤄진 실험 후 웨이드는 암을 치료할뿐더러 무한한 재생 능력을 얻으며 불사의 존재가 된다. 하지만 동시에 부작용으로 호러영화에 어울릴 법한 외양을 갖는다. 스스로 슈트까지 지어 입고 데드풀이 된 웨이드는 자신을 고문한 자를 찾아 제대로 복수한 뒤 당당히 바네사 앞에 나서려 한다.','/k1e0TlvDM4KsiSRyJENVrHxMqtK.jpg','데드풀','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.711007+09',299804,'019bae84-e177-702e-be2e-f2c12b35cade'::uuid,'','/qm9L6t21w9001o4qW51VwLzRcqU.jpg','怪談・牡丹燈籠 もっともっと、愛されたかった。','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.711052+09',1477388,'019bae84-e177-70e8-be31-04345412b3c7'::uuid,'남편한텐 비밀, 내게 딱 맞는 직장을 찾았다!?INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:25:02.711111+09',932624,'019bae84-e177-71d9-be35-dac05e1bc826'::uuid,'대학교 퀸카인 진영을 짝사랑하는 인구. 진영에게 고백할 기회를 엿보지만 용기가 나질 않는다. 어느 날 학교 복도에서 훤칠한 킹카 남자에게 고백을 받는 진영을 보게 된 인구. 그의 고백을 거절하는 모습에 왠지 모를 자신감이 생긴 인구는 고백할 결심을 하고 속마음을 담은 편지를 준비한다. 하지만 하필 고백하려던 날 유일한 절친인 영식에게 선수를 빼앗기고, 보란 듯이 까인 영식의 모습에 간신히 생긴 용기마저 잃고 만다. 좌절한 인구는 홧김에 군입대를 지원하고 만다. 그렇게 입대를 이틀 앞둔 날이자 대학 종강일. 우연히도 진영이 자신이 입대하는 날 어학연수를 가게 된다는 사실을 알게 된다. 그날 밤 친구들과 함께 진영의 송별회를 갖게 되는데, 모두가 술에 취해 잠든 늦은 밤 눈을 뜬 인구. 짧은 치마를 입고 눈 앞에 잠들어 있는 진영의 모습을 마주하게 되는데…','/fCgrd1v5tSQZDlAmxEioWQREkoQ.jpg','뜨거운 밤이 열리면2','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.711125+09',187164,'019bae84-e177-7213-be36-bef22188bb28'::uuid,'','/v4sdyZ7iTR9BH6x7arKUjx8tPAm.jpg','Un millón en la basura','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.711139+09',371493,'019bae84-e177-724c-be37-71c6dad8417d'::uuid,'','/5VzyGj3uBrrIUY6OesgwZZ9NttI.jpg','Cayó de la gloria el diablo','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.711153+09',297762,'019bae84-e177-7285-be38-f8f4140d4970'::uuid,'수천년 간 존재를 숨긴 채 지구를 수호하던 데미스키라의 공주 다이애나는 어느 날 하늘에서 이상한 움직임을 포착한다. 1차 세계대전에 참전해 스파이 활동을 벌이다가 격추된 미국인 조종사 스티브가 해변에 불시착한 것. 태어나 처음으로 남성을 보게 된 다이애나는 호기심을 감추지 못하고, 데미스키라의 일원들은 그가 파멸을 가져올 수도 있음을 경고한다. 다이애나는 엄마이자 여왕인 히폴리타의 반대에도 불구하고 나치군의 추격을 따돌리면서 그들의 생화학무기 공격을 비밀리에 막아야 하는 스티브를 따라나선다.','/oZGYR75RaSLQ8XdJIVerYnOdhFx.jpg','원더 우먼','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.711169+09',807,'019bae84-e177-72d3-be39-f4b49595a379'::uuid,'은퇴를 7일 앞둔 관록의 형사 윌리엄 소머셋(모건 프리먼)과 새로 전근 온 신참내기 형사 밀스(브래드 피트)가 팀이 된 바로 다음날, 강압에 의해 위가 찢어질 때까지 먹다가 죽은 초고도 비만 남자와 역시 강압에 의해 식칼로 자기 살을 베어내 죽은 악덕 변호사의 사건과 마주한다. 식탐, 탐욕, 그리고 나태, 분노, 교만, 욕정, 시기. 소머셋은 현장에 남은 흔적들로 단테의 신곡과 쵸서의 캔터베리 서사시를 근거로 한 기나긴 연쇄 살인이 시작되었음을 직감하고 성서의 7가지 죄악을 따라 발생하는 사건들을 추적하기 시작하는데...','/izzk8dbmrLowcoGbFaebqJvzyXg.jpg','세븐','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.711187+09',793387,'019bae84-e177-730e-be3a-4ffcf85037f6'::uuid,'악마와 그를 쫓는 어둠의 숭배자들로 인해 혼란에 빠지게 된 도시. 공권력조차 이들 앞에서 무력해지자 특별한 능력을 가진 어둠의 해결사 거룩한 밤 팀 바우, 샤론, 김군이 직접 악의 무리를 처단하고자 한다. 그러던 중 갑자기 동생 은서가 이상증세를 보인다는 의뢰인 정원이 찾아오고 그 안에서 지금껏 본 적 없던 강력한 존재의 기운을 느끼는데… 과연 거룩한 밤 팀은 악의 무리에 맞서 세상을 구원해 낼 수 있을까?','/7MGnHpfhF8savUsrUJoI8Q7dTk9.jpg','거룩한 밤: 데몬 헌터스','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.711201+09',808,'019bae84-e177-7347-be3b-c07ea764f557'::uuid,'성 밖 늪지대에 사는 엄청나게 못생기고 무지무지 큰 괴물 슈렉. 지저분한 진흙으로 샤워를 즐기고 동화책은 화장실 휴지 삼아 쓰는 그는 혼자만의 시간을 즐긴다.  그러던 어느 날, 자신만의 고요한 안식처에 백설공주, 신데렐라, 빗자루를 타고 다니는 마녀, 피리부는 아저씨, 피터팬, 피노키오 등등.. 동화속의 주인공들이 모두 쳐들어온다. 그 중에서도 가장 귀찮은 건 쉴새없이 떠들어대는 당나귀 덩키. 알고보니 얼굴이 몸의 반을 차지하는 1m도 안되는 숏다리 파콰드영주가 동화속의 주인공들을 다 쫓아낸것. 결국 슈렉은 파콰드영주와 담판을 지으러 떠난다.  하지만 일은 이상하게 꼬여 결국 파콰드영주 대신 불뿜는 용의 성에 갇힌 피오나 공주를 구하러 떠나게 되는데..','/hABnmgdAU3u6Nu61b9GUGaOseVl.jpg','슈렉','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.711216+09',187179,'019bae84-e177-7386-be3c-3132def98551'::uuid,'',NULL,'海外情歌','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.71123+09',1116984,'019bae84-e177-73bf-be3d-c1747bee49ec'::uuid,'','/yiEkGNiXPKgyRGyqy3MfCVEoRx1.jpg','All You Need Is Death','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.711245+09',810,'019bae84-e177-73ff-be3e-e0af7794a024'::uuid,'마침내 평온을 되찾은 ‘겁나먼 왕국’.  이제 자신들의 늪에 돌아가 둘만의 달콤한 생활을 꿈꾸던 슈렉과 피오나에게 엄청난 태클이 들어온다. 피오나의 아버지 해롤드 왕이 위독해져 슈렉과 피오나가 왕위를 계승해야 하는 상황이 벌어진 것.  해롤드 왕은 슈렉에게 왕위 계승 다음 서열인 피오나의 먼 친척 ‘아더 왕자’를 찾아오면 늪으로 돌아가도 좋다는 타협책을 내놓는다. 슈렉은 동키, 장화 신은 고양이와 함께 아더 왕자를 찾기 위한 머나먼 여정에 나서고….  한편, 슈렉이 없는 틈을 ‘프린스 챠밍’은 동화속 악당을 모아 겁나먼 왕국을 차지하려는 음모를 꾸미고, 왕국에 남아있는 피오나 등 5공주(백설공주, 신데렐라, 잠자는 숲속의 공주, 라푼첼)와 릴리안 왕비는 힘을 합쳐 프린스 챠밍에 맞서는데….  ‘모두가 王이 되고자 하는 시대’에 ‘스스로 王을 포기하려는’ 슈렉. 자신이 원하는 삶을 누리는 ‘진정한 王’이 될 수 있을까?','/s8VjSynQ1wGwkALwmn5nsifivyq.jpg','슈렉 3','MOVIE');
INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:25:02.711261+09',228137,'019bae84-e177-743e-be3f-311bc54dad0f'::uuid,'','/vaCWR8letn8Vsl1hr5mlblVznZD.jpg','Brácha za všechny peníze','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.711275+09',987940,'019bae84-e177-7478-be40-e6b5e7e28c2d'::uuid,'',NULL,'Pan Větrovský z Větrova a paní Deštná z Dešťova a také Martin a Klaudina','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.711289+09',70447,'019bae84-e177-74b2-be41-afdc36c96ac4'::uuid,'미국 루이지애나 주 남부의 작은 만. 고요하고 때묻지 않은 이 지역에 한 소년이 가족과 함께 살고 있다. 어느 날 그의 아버지가 석유 시추 회사에 가족의 땅을 내어주고, 그들의 삶의 터전이 변모하기 시작한다. 유정탑은 점점 높아져 가는데, 늑대인간과 인어를 믿던 소년의 세계는 어떻게 될 것인가?','/kwEbsHAvdY9G2gJKRKYmxJ6IB6L.jpg','루이지애나 스토리','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.711303+09',267050,'019bae84-e177-74ec-be42-e3d146cd65a4'::uuid,'','/fjtxFbCoyWw43tvhtr7dPfJ4gq8.jpg','Vento di primavera','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.711319+09',447273,'019bae84-e177-7531-be43-d3bffbadd92d'::uuid,'눈보라가 몰아치던 겨울 밤 태어난 백설공주. 온정이 넘치던 왕국에서 모두의 사랑을 받았지만, 강력한 어둠의 힘으로 왕국을 빼앗은 여왕의 위협에 숲으로 도망친다. 마법의 숲에서 간신히 살아남은 백설공주는 신비로운 일곱 광부들과 만나게 되며 새로운 세상을 마주하고, 마음속 깊이 숨겨진 용기와 선한 힘을 깨닫게 된다. 그리고 마침내, 빼앗긴 왕국을 되찾기 위해 여왕과 맞서 싸우기로 결심하는데…','/7EruTgYzDFM8kWhr2ysuuwoXFqk.jpg','백설공주','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.711335+09',1235746,'019bae84-e177-756d-be44-b020d70c246a'::uuid,'"눈과 얼음이 덮은 미네소타, 평범한 여인의 사투가 시작된다"INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:25:02.711413+09',1084199,'019bae84-e177-76ac-be49-023c7763b1b9'::uuid,'서로에게 딱 맞는 커플 ‘아이리스’와 ‘조시’는 친구들과 함께 호숫가의 별장으로 호화로운 휴가를 떠난다. 하지만 그곳에는 충격적인 사건이 기다리고 있는데…','/dq7CEYFCvQPfYIpAXOvJr3w6VLY.jpg','컴패니언','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:02.711427+09',357170,'019bae84-e177-76e6-be4a-e562a485aa61'::uuid,'','/dFX97EVitLQCym0ISTNmOrKcGNS.jpg','The Birds of Anger','MOVIE'),
