INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:25:13.686258+09',285506,'019bae85-0c56-7434-9002-7f2de87eadca'::uuid,'',NULL,'Die Zeiten ändern sich','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:13.686272+09',1114967,'019bae85-0c56-746c-9003-97ca2a001b5f'::uuid,'길 잃은 영혼의 수호천사가 되고 싶지만, 현실은 운전 중 문자하는 인간들을 보호하는 작은 날개의 초짜 천사 가브리엘. 열심히 살아도 차에서 노숙하는 삶을 못 벗어나며 절망에 빠진 N잡러 아지를 구원하기 위해 금수저인 벤처 투자자 제프와 삶을 바꿔준다. 하루아침에 극과 극으로 변한 아지와 제프의 삶은 가브리엘의 의도와 다르게 흘러가고, 이에 대한 책임으로 가브리엘은 날개를 반납하고 인간으로 강등당하는데… 인생이 뒤바뀐 아지와 제프, 인간이 된 가브리엘 이 세 남자의 유쾌한 좌충우돌 운명 재도전기가 펼쳐진다!','/mlpVu3aq1cOjlHOxd70NILlj1fc.jpg','굿 포츈','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:13.686287+09',627535,'019bae85-0c56-74a9-9004-0f96e341993d'::uuid,'','/70wtwb8qP2V2l1Fg7n5rYu4PCKL.jpg','বর্ণ পরিচয়','MOVIE'),
