	 (0.0,0,'2026-01-12 04:25:13.687901+09',472081,'019bae85-0c57-7e7d-a194-888a199e7e08'::uuid,'','/f5CEmS9vhXYdF46Ybjxlz2lWGBP.jpg','Dinner for One auf Nordhessisch: Als so wie Alszus','MOVIE');
INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:25:13.687915+09',384018,'019bae85-0c57-7eb6-a195-3fdac02f86ef'::uuid,'이상한 약물에 의해 강력한 파워를 얻게 된 아나키스트 브릭스턴 로어는 인류를 천천히, 그리고 영원히 다른 존재로 바꿔버릴 수 있는 생화학무기를 손에 넣고 자신은 진화형 인간이 된다. 그런데 데카드 쇼의 동생이자 M16 요원인 해티 쇼가 치명적인 병원균이 들어 있는 실린더를 브릭스턴의 손에서 훔쳐 달아난다. 양국으로부터 해티의 행방을 찾아달라는 명령을 받은 루크와 데카드는 유전자 조작으로 사실상 파괴 불가능한 존재가 되어버린 브릭스턴을 상대로 힘겨운 싸움도 이겨나가야 하는데...','/8MdVJYHKp7JFvTMkLkZOou13LYV.jpg','분노의 질주: 홉스 & 쇼','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:13.68793+09',152601,'019bae85-0c57-7ef4-a196-3dbb4eadc055'::uuid,'테오도르는 다른 사람들의 편지를 대신 써주는 대필 작가로, 깊이 아꼈던 아내와 이혼 소송 중이다. 타인의 마음을 전해주는 일을 하고 있지만, 정작 테오도르 자신은 너무 외롭고 공허한 삶을 살고 있다. 그러던 어느 날, 스스로 생각하고 느끼는 인공 지능 운영체제인 사만다를 만나게 된다. 사만다는 따뜻한 목소리와 뛰어난 전산처리 능력을 통해 테오도르가 더 편안한 삶을 살 수 있도록 돕고, 테오도르는 자신의 육체를 통해 사만다가 더 많은 세계를 경험할 수 있도록 격려한다. 그렇게 둘은 직접적인 접촉보다 밀도 높은 정신적 교감을 나누는데...','/thUJI82kWMxA2jtjLtPxDIj67tY.jpg','그녀','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:13.687944+09',1010705,'019bae85-0c57-7f2d-a197-9ab578b3e82d'::uuid,'','/7CssoRj5MYnFtNVdNWDZnYNwnxp.jpg','The Great Wolf Pack: A Call to Adventure','MOVIE'),
