INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:25:13.68887+09',324786,'019bae85-0c58-7dfb-a2b6-262bc14cee99'::uuid,'비폭력주의자인 도스는 전쟁으로부터 조국과 소중한 사람들을 지키기 위해 총을 들지 않아도 되는 의무병으로 육군에 자진 입대한다. 총을 들 수 없다는 이유로 필수 훈련 중 하나인 총기 훈련 마저 거부한 도스는 동료 병사들과 군 전체의 비난과 조롱을 받게 된다. 결국 군사재판까지 받게 되지만 끝까지 자신의 신념을 굽히지 않은 도스에게 군 상부는 오키나와 전투에 총기 없이 의무병으로 참전할 것을 허락하는데…','/nlvcNogJK9R9iIj0YINApQE36FF.jpg','핵소 고지','MOVIE'),
