	 (0.0,0,'2026-01-12 04:25:13.690029+09',836952,'019bae85-0c5a-7088-bf83-5bcb1e5238fd'::uuid,'','/wMlZbfNVAs6PSB9Nd2GtDuOxvs.jpg','媽媽的遙控器','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:13.690043+09',445776,'019bae85-0c5a-70c0-bf84-3fec78dc8fd3'::uuid,'','/yUer9W6oIYF8j4YdSod5IYemZ3W.jpg','No Coração dos Deuses','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:13.690058+09',163163,'019bae85-0c5a-70ff-bf85-541741a24dd2'::uuid,'','/AcuSN0ATlQcfy7tbccncwo2pwNg.jpg','Lelíček ve službách Sherlocka Holmesa','MOVIE');
