	 (0.0,0,'2026-01-12 04:25:24.293902+09',449002,'019bae85-35c5-7e7e-ba4a-c1772c431b3a'::uuid,'','/5iMrObe7yqw2jdgiGxpTJAB9GDX.jpg','As Tentações do Irmão Sebastião','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:24.293917+09',737767,'019bae85-35c5-7ebf-ba4b-48ac9a0f66b1'::uuid,'','/arvQIxkrEH9jRuj2zl3tCngKaEK.jpg','Un monde flottant','MOVIE'),
