INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:25:34.820709+09',460816,'019bae85-5ee4-7b6a-b6c7-7eb9ef000fe1'::uuid,'','/iMHuLxRIvvCzU4hPAorFnxUCcQW.jpg','The Enchanted Cottage','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:34.820723+09',1370124,'019bae85-5ee4-7ba5-b6c8-c7b1801af435'::uuid,'','/k7QB1I0VJgD8ibYv7slV2YtMCrO.jpg','Sin cobertura','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:34.820739+09',1245193,'019bae85-5ee4-7be6-b6c9-819d915095bc'::uuid,'아일랜드 디자이너 아일린 그레이는 1929년, 코트다쥐르에 은신처를 지었다. 그 첫 번째 집은 독자적인 양식의 아방가르드 걸작이었다. 그녀는 함께 지은 장 바도비치의 이니셜과 자신의 이니셜을 신비롭게 결합하여 그 집에 E.1027이라는 이름을 붙였다. 이 집을 알게 된 르 코르뷔지에는 강하게 끌리며 집착하게 되고, 집 벽에 벽화를 그려 덮어버리고서 사진을 찍어 출판한다. 그레이는 이 그림들을 파괴 행위로 정의하고 배상을 요구하지만, 코르뷔지에는 이를 무시한 채 대신 E.1027 바로 뒤에 그 유명한 카바농을 짓는다.','/2d0zF6pMCr5nl2rCDqKyckIeYF9.jpg','아일린 그레이 E.1027','MOVIE'),
