INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:25:34.824916+09',1335832,'019bae85-5ee8-7eb9-beae-1757841abb12'::uuid,'','/hXv7yjaixDcZ77nni0q8f2m1Tvb.jpg','Coco Chanel et Elsa Schiaparelli, le noir et le rose','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:34.824931+09',10764,'019bae85-5ee8-7efa-beaf-36c9f0d892a6'::uuid,'카지노 로얄에서 최초의 임무를 성공적으로 완수한 007 제임스 본드. 하지만 첫사랑 베스퍼의 배신과 비극적인 죽음으로 강렬한 복수심에 휩싸인다. 한편 진실을 밝히기 위해 M과 함께 수수께끼의 인물 미스터 화이트를 심문하던 중, 베스퍼를 죽음으로 몰고간 배후 세력이 생각보다 훨신 거대하고 위험한 조직임을 알게 된다. 게다가 MI6 내부에까지 세력이 침투해 있어 제임스 본드가 믿을 수 있는 사람은 아무도 없다는 게 밝혀진다. 단서를 쫓던 007은 MI6 내의 누군가가 테러 조직의 돈 세탁을 위해 아이티에 은행 계좌를 만들었다는 정보를 입수하고 곧바로 아이티로 향하는데...','/q1s0OFBJPQXNJ0FKeDCCOoKR70D.jpg','007 퀀텀 오브 솔러스','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:34.824946+09',1530395,'019bae85-5ee8-7f36-beb0-2d5f358f0357'::uuid,'','/tDkjykdOXTTSgqNVkn6qOP1LJsD.jpg','Война и мир','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:34.824961+09',119308,'019bae85-5ee8-7f71-beb1-0f94ab95e326'::uuid,'','/hERsprO7lr76EXHzK7vlwU9lbI1.jpg','Hasta el viento tiene miedo','MOVIE'),
