INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:25:34.834497+09',18239,'019bae85-5ef2-7806-871d-33fd18101f84'::uuid,'초능력을 가진 뱀파이어 에드워드는 인간 벨라가 자신 때문에 위험해지자 냉정하게 그녀를 떠난다.  이제 벨라를 지키는 것은 오랜 친구 제이콥. 하지만 제이콥은 뱀파이어와 적을 이루는 늑대인간 ‘퀼렛족’의 일원으로 벨라와 에드워드를 떼어놓고자 한다.  그러던 어느 날 벨라는 자신이 위험한 사고를 당할 때마다 에드워드의 환영이 보인다는 것을 알고 급기야 절벽에서 떨어지는 무모한 행동을 한다. 그리고 이 사건은 누구도 예상치 못할 결과를 초래하는데…  인간과 뱀파이어의 위험한 사랑! 어둠을 지배하는 절대 세력의 탄생!  올 겨울, 운명에 맞선 거대한 대결이 시작된다!','/q1zQIaDMBgLzpW8Hikzhau1InvI.jpg','뉴 문','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:34.834512+09',1173331,'019bae85-5ef2-7841-871e-08129e1036d2'::uuid,'','/ylYsIGCpqEBOa1fmJ454oV21OJa.jpg','South America: A New Look','MOVIE'),
