	 (0.0,0,'2026-01-12 04:25:45.479935+09',569486,'019bae85-8887-7f09-aa47-4cca13742569'::uuid,'작가이자 뮤지션인 PJ 하비는 그녀의 새 앨범과 관련된 창의적인 영감을 얻기 위해 전세계를 떠나기로 계획한다.INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:25:45.48008+09',827541,'019bae85-8888-7159-98bc-fedb6dbc531e'::uuid,'','/dGpjfpIbhm8QSEZvgdxQ0iucFkD.jpg','La Cascade, Exposition de Genève','MOVIE'),
