	 (0.0,0,'2026-01-12 04:25:45.481325+09',262458,'019bae85-8889-7546-a25d-4ae5fd131096'::uuid,'','/cTGWo7wOtovqVSn2x1c4XfJprQu.jpg','Los días del pasado','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:45.481342+09',819533,'019bae85-8889-758a-a25e-8157d798881b'::uuid,'','/eaY1ThOrv4XF8kuMfS5I82PUJGJ.jpg','Pompei - Eros e mito','MOVIE');
