INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:25:45.487995+09',11423,'019bae85-888f-7ffe-8f91-11f5158ac37c'::uuid,'1986년 경기도. 젊은 여인이 무참히 강간, 살해당한 시체로 발견된다. 2개월 후 비슷한 수법의 강간살인사건이 연이어 발생하면서 사건은 세간의 주목을 받기 시작하고, 일대는 연쇄살인이라는 생소한 범죄의 공포에 휩싸인다. 사건 발생 지역에 특별수사본부가 설치되고, 수사본부는 구희봉 반장을 필두로 지역토박이 형사 박두만과 조용구, 그리고 서울 시경에서 자원해 온 서태윤이 배치된다. 육감과 폭력으로 수사를 진행하는 박형사와 증거와 과학수사를 추구하는 서형사는 수사 내내 마찰을 일으키는데...','/3I1Ng4sxDUyPOdVu3lQ20N14PGE.jpg','살인의 추억','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:45.488011+09',429220,'019bae85-8890-703f-b819-e797b0d821a5'::uuid,'','/dPx7qtGAtoSLUDZ6rwTolWYB8jo.jpg','JFK: The Private President','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:45.488026+09',1275067,'019bae85-8890-707c-b81a-85dc02e849c1'::uuid,'','/5GEVcoO2dkFlWLnGur3DDc0n7D6.jpg','Benjamin Britten and His Festival','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:45.48804+09',967847,'019bae85-8890-70b7-b81b-3c4f636cf13a'::uuid,'무더운 여름의 뉴욕의 어느 날, 고대 유물 속 깨어난 데스칠로 인해 정체불명의 냉기가 몰려오고 마침내 도시는 얼어붙고 만다. 유령을 퇴치하는 그루버슨과 라이즈 버스터즈 멤버들은 얼어붙은 세상을 깨부수기 위해 유령 군단을 쫓기 시작하는데…','/mGzSIfzmcf9H91DS06cnka1SYrP.jpg','고스트버스터즈: 오싹한 뉴욕','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:45.488056+09',922786,'019bae85-8890-70f8-b81c-c5acb19caecb'::uuid,'','/hTUpcaVSAIY1WM6GkHBpBxzDwZ3.jpg','Monte Carlo: C''est La Rose','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:45.488071+09',980128,'019bae85-8890-7134-b81d-6702a15a5e22'::uuid,'','/vqEg5vYEO92wMzhKgBvBD913fK3.jpg','The Killing Tree','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:45.488085+09',64688,'019bae85-8890-716f-b81e-ef1359c6db19'::uuid,'고등학교 시절을 전혀 다르게 보낸 운동만 할줄 아는 젠코(채닝 테이텀)와 공부만 할 줄 아는 슈미트(조나 힐). 하지만, 둘다 ''프롬(졸업 무도회)''을 못가긴 마찬가지였다. 졸업후 경찰학교에서 다시 만난 이둘은 서로의 약점을 채워주며 둘도 없는 단짝이 된다. 의욕에 불타는 초보 경찰이었지만 결국 곱상한 외모(?)때문에 고등학교 잠복근무로 부서 이동되어 버린다. 신종 약물이 활개치는 ''21 점프 스트리트''의 한 고등학교에서 그 시절과는 정 반대의 고교생활이 펼쳐진다.','/8frigUQH9rpSasBwMKoNPCzvjCW.jpg','21 점프 스트리트','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:45.488104+09',951487,'019bae85-8890-71bc-b81f-603b57b6d34f'::uuid,'','/pFZONoPgtrzjCKeYWs7O7toxIKy.jpg','Down Home Music - A Journey Through the Heartland','MOVIE'),
	 (0.0,0,'2026-01-12 04:25:45.488119+09',1377447,'019bae85-8890-71f8-b820-02da35096e40'::uuid,'',NULL,'The Montreal Protocol','MOVIE'),
