	 (0.0,0,'2026-01-12 04:26:06.998283+09',649473,'019bae85-dc96-7499-8a7a-3b779bbad037'::uuid,'','/cLLhGEQt1T3LdSaZtzP4vLuVyfT.jpg','Servus Uli – Ein Leben für den FC Bayern','MOVIE'),
	 (0.0,0,'2026-01-12 04:26:06.998297+09',1317149,'019bae85-dc96-74cf-8a7b-2266e35fb56a'::uuid,'','/vUwyhNWBKkSwK8ELvEeBRwV724h.jpg','I Swear','MOVIE');
