	 (0.0,0,'2026-01-12 04:26:17.621377+09',719628,'019bae86-0615-761b-966d-a8b8a5a1cd9e'::uuid,'','/Ap9Xi1qoKubGnKQPmtxzekaV4cu.jpg','구의역 3번 출구','MOVIE'),
