INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:26:17.621421+09',29457,'019bae86-0615-76d0-9670-0952aff27e24'::uuid,'70년대 말의 마르틴 프랭크의 소설을 영화한 작품이다. 이 영화는 70년대 초의 취히리를 배경으로 록그룹의 열열한 팬인 베니와 록그룹 리더이며 베니보다 8상 연상인 포기의 이야기이다. 베니는 포기의 마약값을 마련하기 위해 몸을 파는일 마저도 주저하지 않는다. 결국에는 육체적 도덕적 타락과 우유부단한 포기에 대한 환멸로 베기는 자신의 사랑을 포기한다. 르몽드지는 어리석은 시트콤처럼 시작하여 파괴적 사랑에 대한 감독 자신의 세계를 강요하며 영화를 끝낸다고 혹평했다.','/up41igEjQJBltYXqbZjpkOLrL9F.jpg','포기는 나쁜 놈','MOVIE'),
	 (0.0,0,'2026-01-12 04:26:17.621436+09',1006366,'019bae86-0615-770a-9671-9a135409e348'::uuid,'','/bdbktpm9srzTh3wA75PDDR2egBC.jpg','The Difference Between Pipi & Pūpū','MOVIE'),
	 (0.0,0,'2026-01-12 04:26:17.62145+09',834334,'019bae86-0615-7742-9672-4dd8384d9fc2'::uuid,'','/x2EAfAwIjlj8Scm1wxeGTspGb2t.jpg','Fosforito: una historia de flamenco','MOVIE'),
