INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:26:17.622741+09',1487783,'019bae86-0616-7bec-a60e-1f6181aebf21'::uuid,'','/iVrdmH073Dv0XA19u6OLmR5pSLt.jpg','The Difference Between Us','MOVIE'),
	 (0.0,0,'2026-01-12 04:26:17.622755+09',947,'019bae86-0616-7c26-a60f-81ae2e3c0d46'::uuid,'영국 정보국 소속 장교 로렌스 는 1차대전 중 중동지역의 전투에서 아랍 부족의 지원을 받기 위해 아랍 지역으로 파견된다. 그런데 그는 영국 정부가 바라던 것 이상으로 아랍의 지도자들을 사로 잡고 아랍의 독립을 위해 열심히 싸워 아랍 민족으로 부터 ‘아라비아의 로렌스’라는 영웅적인 칭호를 받게 된다. 그는 아랍 전사들을 이끌고 터키군들과 싸우면서 규율을 잡기 위해 남의 마을의 우물물을 마신 병사를 과감히 처형하는 등 독한 모습을 보여준다. 그러나 그의 그런 용맹성은 터키 군에게 포로로 잡힌 후 그곳에서 받은 성적 학대를 통해 병적으로 발전된다. 그리고 마침내 영국 정부의 소환을 받고 런던으로 돌아오지만 중동으로 보내 줄 것을 요구하면서 사막으로 돌아가길 원한다. 그러나 이미 정치적으로 타결이 된 아라비아 사막은 그를 원치 않았는데.','/p2PG2nXE4e6piHdAcDLhDlCA30E.jpg','아라비아의 로렌스','MOVIE'),
