INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:26:28.260299+09',1229831,'019bae86-2fa4-74db-bfe3-d7a9a14fe307'::uuid,'','/lDU1TI5baS0yoyrk1dHZQXPrJyB.jpg','XXL','MOVIE'),
	 (0.0,0,'2026-01-12 04:26:28.260313+09',11287,'019bae86-2fa4-7513-bfe4-531638941f20'::uuid,'1934년 미국 프로야구는 선수들이 전쟁에 참전하자 고육지책으로 각지에서 여자 야구선수들을 선발하여 6개의 여자 프로야구팀을 만든다. 우연히 스카웃 담당자의 눈에 띄여 입단하게 된 도티와 키트 자매는 복숭아팀에 배속되어 고된 훈련을 받는다. 야구선수가 됐다는 기쁨에 들뜬 선수들이 열심히 훈련과 경기에 임하자 매일 술만 마시던 듀간 감독도 선수들의 열성에 감동, 열과 성을 다해 선수들을 지도하고 관중들도 차츰 여자야구에 흥미를 갖기 시작한다. 그러던중 포수인 도티가 두각을 나타내자 동생 키트는 질투를 느껴 사사건건 언니에게 트집을 잡는다. 그로인해 결국 키트는 라이벌팀 라신느 벨스로 이적되고 월드시리즈에 진출한 복숭아팀은 라신느 벨스와 결승전에서 맞붙게 된다.','/a19LtYH9qxuayd5nF0SKZh1uC1c.jpg','그들만의 리그','MOVIE'),
	 (0.0,0,'2026-01-12 04:26:28.260327+09',384029,'019bae86-2fa4-754c-bfe5-0019d9c709e2'::uuid,'','/lbvjAo6259rjnqI0IvgY5juxVGP.jpg','എഗൈൻ കാസർകോട് കാദർഭായ്','MOVIE'),
	 (0.0,0,'2026-01-12 04:26:28.260341+09',1496079,'019bae86-2fa4-7585-bfe6-8b280183cf53'::uuid,'',NULL,'What the Curate Really Did','MOVIE'),
	 (0.0,0,'2026-01-12 04:26:28.260356+09',873492,'019bae86-2fa4-75c3-bfe7-f0d297a43ef9'::uuid,'어느 날, 오랜만에 에스더의 집에 그녀의 친구들이 놀러오고 그들은 밤새도록 마작 게임을 즐긴다. 게임을 하던 중, 평소에 앙숙이었던 에스더의 친구인 암파로와 새 남편인 레오가 신경전을 벌이고 말싸움이 걷잡을 수 없이 커지게 된다. 결국, 암파로는 모두 앞에서 레오에 대한 충격적인 사실을 폭로하고, 분노한 레오는 그녀를 살해하는데···.','/bOWuycAHVWoAXy6gFPVoPbdtYGM.jpg','쾌락의 밤','MOVIE'),
