INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:26:28.260854+09',1082466,'019bae86-2fa4-7dbb-8008-0ad1f0d9f8e7'::uuid,'',NULL,'Dialogue of the Devil Dolls','MOVIE'),
	 (0.0,0,'2026-01-12 04:26:28.260868+09',9331,'019bae86-2fa4-7df6-8009-5422a8529973'::uuid,'CIA 분석가 잭 라이언 박사(해리슨 포드 분)는 그리어 국장(제임스 얼 존스 분) 밑에서 일하고 있다.  어느날 한 요트에서 하든이란 사람의 일가족과 승무원이 살해되는 사건이 일어나고 대통령과 친분이 있는 하든에 대한 수사는 점점 열을 더해가게 된다. 이때 그리어 국장이 암 선고를 받게 되어 병원에 입원하자, 라이언은 이 사건의 수사에 뛰어들게 된다.  라이언은 하든에게 거액의 돈이 해외로부터 입금되어 있는 것을 알게 된다. 이를 계기로 라이언은 하든이 마약 조직인 칼텔 조직과 연계하여 그들의 돈 세탁에 관여했고, 대통령은 하든이 자신의 친구였다는 사실과 하든의 구좌에 들은 돈을 국고로 돌릴 셈으로 일을 추진한 것을 알게 된다.  카르텔에 대한 무력 보복이 조용히 시작되고, 이에 화가 난 카르텔의 보스인 애스케베도(미구엘 샌도발 분)는 다른 보스들의 짓이 아닌가 의심하게 되는데...','/3BMgtajL595Wu0wQF4YdM7Pxhfc.jpg','긴급 명령','MOVIE'),
	 (0.0,0,'2026-01-12 04:26:28.260882+09',797819,'019bae86-2fa4-7e30-800a-e8754299476b'::uuid,'','/jw3joo15IPMDgVhDMk5pofsspfT.jpg','La sexta alumna','MOVIE'),
	 (0.0,0,'2026-01-12 04:26:28.260898+09',779388,'019bae86-2fa4-7e6e-800b-1855281b06a4'::uuid,'','/wDmyMIxzTrefVpTEnS48pj3ILMp.jpg','Return From ISIS','MOVIE'),
	 (0.0,0,'2026-01-12 04:26:28.260913+09',9336,'019bae86-2fa4-7ead-800c-0b50fc384f91'::uuid,'경찰관이 되기 위해 거쳐야 하는 학교, 폴리스 아카데미에서 벌어지는 심술 사나운 교관들과 거친 신병들 사이의 대결을 유쾌한 웃음으로 꾸민 액션 코믹 영화. 권총을 실컷 쏴보고 싶어하며 정의감에 불타는 ''테클베리''(데이빗 그라프), 경찰서장의 종용으로 마지 못해 입학한 ''마호니''(스티브 구텐버그), 동네 건달에게 복수하려고 입학한 ''바바라''(도노반 스콧), 플레이보이 ''죠지 마틴''(앤드류 루빈), 미모의 ''톰슨''(킴 캐트럴), 거인 흑인이며 순정파 ''하이타워''(버바 스미스) 등이 폴리스 아카데미에서 사건을 벌일 인물들이다.','/qxUkWoFI7rF1KUgTgbE3UJEQuvG.jpg','폴리스 아카데미','MOVIE'),
	 (0.0,0,'2026-01-12 04:26:28.260927+09',40056,'019bae86-2fa4-7ee6-800d-d5377f8d99b7'::uuid,'','/m1cvzgWFPL3zekLse6jgXlEXXcs.jpg','Prom Queen: The Marc Hall Story','MOVIE'),
	 (0.0,0,'2026-01-12 04:26:28.260941+09',238715,'019bae86-2fa4-7f1f-800e-f5bd2435da0f'::uuid,'','/jLFsM7E76Xth4SOfEyuYXeZ2inB.jpg','Lieben','MOVIE'),
	 (0.0,0,'2026-01-12 04:26:28.260956+09',834672,'019bae86-2fa4-7f5e-800f-e6e400c8064e'::uuid,'','/REQocPPmG3jaGodDkwfZf01939.jpg','Fearless, The Story of the Isle of Man TT Motorcycle Race','MOVIE'),
	 (0.0,0,'2026-01-12 04:26:28.26097+09',652405,'019bae86-2fa4-7f97-8010-f0f7f762b0fa'::uuid,'','/2aUZoG2r1jk5D9FsQw4rAw04ReS.jpg','Why','MOVIE'),
	 (0.0,0,'2026-01-12 04:26:28.260984+09',99459,'019bae86-2fa4-7fd0-8011-75bfa3bd4822'::uuid,'','/1imutUa0DiJ1DSPGt4JJUvEwCgM.jpg','Onkel Bill fra New York','MOVIE');
