INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:26:38.926678+09',753895,'019bae86-594e-7aed-bf02-a089eb699413'::uuid,'',NULL,'Il ne fait pas chaud','MOVIE'),
	 (0.0,0,'2026-01-12 04:26:38.926694+09',1396965,'019bae86-594e-7b2c-bf03-bce1b7339f25'::uuid,'국립천문대 노베야마의 괴한 침입 사건을 조사하던 나가노현경 형사 야마토 칸스케. 사건을 수사하던 중, 천문대의 파라볼라 안테나가 움직이자 10개월 전 눈사태 속 총격 피습으로 인한 왼쪽 눈의 상처에 갑자기 통증이 이는데… 그날 밤, 모리 코고로에게 형사 시절의 옛 동료 와니 형사의 전화가 걸려 온다. 나가노현 눈사태 사고의 내막을 조사하고 있던 와니는 사건 파일에서 모리 탐정의 이름을 발견, 참고 차 모리 탐정과 만나기로 한다. 약속 당일, 코난과 란도 모리 탐정을 따라 약속 장소로 향하지만 그곳에서 의문의 총성이 울려 퍼진다.','/40nUEiyj9j7y2rryZf1JE9qp8ut.jpg','명탐정 코난: 척안의 잔상','MOVIE'),
	 (0.0,0,'2026-01-12 04:26:38.926709+09',758010,'019bae86-594e-7b69-bf04-8020f4ad247f'::uuid,'','/iBhIVJSQkeuGtYg1bpeEj5xh2zS.jpg','from my kitchen window the building was blinking','MOVIE'),
