INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:26:38.927377+09',84308,'019bae86-594f-761d-bd84-d156fd62c65f'::uuid,'저명한 저널리스트 미구엘은 아름답고 수줍음 많은 언론학도 안젤라를 만나 집에서 인터뷰를 하던 중 사고로 욕실 문이 고장나 둘은 욕실에 갇히게 된다.  그렇게 시작된 두 사람의 치열한 설전.  둘은 여러 가지 주제를 놓고 현학적 토론을 벌이며 상대방을 조금씩 알아가고 가까워진다.  매우 좁고 한정된 공간 안에서 펼치는 문학과 언론, 삶, 욕망과 영감 등 사적이면서 특별한 대화가 펼쳐지는데...','/9rQDTG1bRUUeyWheR47acgqOqXE.jpg','러블리 마드리드','MOVIE'),
	 (0.0,0,'2026-01-12 04:26:38.927393+09',1388867,'019bae86-594f-765d-bd85-28fbb63b557e'::uuid,'',NULL,'Dajana: The Ex Neo-Nazi Trans Woman','MOVIE'),
