INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:26:38.93974+09',509009,'019bae86-595b-7be7-b597-d5b327aba738'::uuid,'','/7VUsefYrKOIcDB9tcT72TFVNRlQ.jpg','All the Devils are Here','MOVIE'),
