INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:26:38.940956+09',273676,'019bae86-595c-7f5c-9ae0-8cf385b47a00'::uuid,'','/7gHZmPypz9aoBFEmhZyytF9qbQ.jpg','Un lío en dólares','MOVIE'),
	 (0.0,0,'2026-01-12 04:26:38.940971+09',132363,'019bae86-595c-7f9b-9ae1-4c4b800b464c'::uuid,'고향을 떠나 워싱턴의 한 호텔에서 일하던 세실 게인즈는 손님을 응대하던 성실하고 진실된 모습이 백악관 관료의 눈에 띄어 꿈에도 생각지 못한 백악관에 들어가게 된다. 1952년부터 1986년까지 무려 34년간 역사의 흐름 속에서 묵묵히 자리를 지키며 8명의 대통령을 수행한 세실 게인즈. 흑인 꼬마에서 최고의 버틀러가 된 그를 통해 지금껏 아무도 몰랐던 백악관 사람들의 감동 실화가 펼쳐진다. 케네디, 닉슨, 레이건 등 8명의 대통령들의 마음을 움직인 그가 올 가을, 관객들의 마음을 움직인다!','/fyPO6SY4hUJaz60yAenbfSJaNQa.jpg','버틀러: 대통령의 집사','MOVIE'),
