INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:26:49.679559+09',82856,'019bae86-834f-790e-bc30-2e492396afc4'::uuid,'은하 제국이 붕괴한 후, 고독한 총잡이는 은하 외곽에서 현상금 사냥꾼 일을 하며 홀로 살아간다.','/9wOTABT35GsYNHtmFnxbRYN9d24.jpg','만달로리안','TV_SERIES'),
	 (0.0,0,'2026-01-12 04:26:49.67958+09',39852,'019bae86-834f-7961-bc31-2da883f8a54d'::uuid,'평범한 젊은 엄마가 처음 보는 남자를 칼로 찔러 죽인다. 그녀 자신마저 알 수 없는 이유로. 그녀를 동정하는 형사는 진실을 찾아 사라진 기억의 미궁 속으로 발을 들인다.','/rmibFGdqOe0kKKhPls0jVOdZCWw.jpg','죄인','TV_SERIES'),
