INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:27:00.619089+09',232230,'019bae86-ae0b-717e-8b08-88a67d84c5b2'::uuid,'<신비의 제왕>은 빅토리아 시대의 유럽풍과 스팀펑크 요소가 어우러진 이세계에서 펼쳐지는 이야기이다. 주명서는 신비로운 세계에서 기이한 죽음을 맞이한 역사과 학생 클레인의 몸에 빙의하여 깨어난다. 평범한 삶을 살던 그는 생각지도 못하게 인생에 큰 변화가 일어나 초자연적인 힘을 얻고, 모험의 소용돌이에 빠진다. 주명서는 초월자 조직에 들어가 위험 가득한 곳에서 싸움을 벌이고 자신을 이 세계로 소환한 배후의 음모를 밝혀 나가는데…','/6d5PPikZbi1nJzeVqaRs1ydLzCd.jpg','신비의 제왕','TV_SERIES'),
