INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:27:00.623511+09',156898,'019bae86-ae0f-783f-a088-369304f2ab84'::uuid,'어둠의 세력이 파괴신 안스라삭스를 부활시키려 하자, 메타 리카나 왕국은 어디로 튈지 모르는 안하무인 마법사에게 도움을 청한다.','/1xhSuBxKgzMRcyDP9i1UPYXrmHk.jpg','바스타드: 암흑의 파괴신','TV_SERIES'),
