INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:27:00.626081+09',106009,'019bae86-ae12-7161-af2f-118325170062'::uuid,'재미있는 숫자 세계로 놀러 오세요. 언제나 즐거운 숫자 친구들이 노래를 부르며 덧셈과 뺄셈을 보여줘요. 1부터 100이 넘는 숫자까지 놀이를 통해 알려주기도 한답니다. 함께 합쳤다가 나뉘기도 하는 신기한 숫자 나라로 떠나요.','/vt872bR11jYDRSzTSfLuOmb2SMt.jpg','넘버블록스','TV_SERIES'),
