INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:27:11.380069+09',235577,'019bae86-d814-7139-8daf-8a31824c3f5d'::uuid,'판사의 몸에 들어간 악마 ‘강빛나’가 지옥같은 현실에서 인간적인 열혈형사 ‘한다온’을 만나 죄인을 처단하며 진정한 판사로 거듭나는 선악공존 사이다액션 판타지','/4rZfFtluuNbBnj2ziadDVaiDZMl.jpg','지옥에서 온 판사','TV_SERIES'),
	 (0.0,0,'2026-01-12 04:27:11.380093+09',153657,'019bae86-d814-719d-8db0-251b6249acb5'::uuid,'강력반 형사에서 사설탐정이 된 해리 보쉬는 경찰의 권한 없이 사건을 수사하느라 애를 먹는다. 변호사 허니 ‘머니’ 챈들러는 살해당할 뻔한 경험 이후 사법 체제에 대한 믿음이 흔들린다. 매디 보쉬는 로스앤젤레스 거리에서 신입 경찰관으로 순찰을 맡으며 가능성과 어려움을 직면한다.','/usknS4tr8FUTm3FVWyLbWEPSGHa.jpg','보슈: 레거시','TV_SERIES'),
	 (0.0,0,'2026-01-12 04:27:11.380116+09',215103,'019bae86-d814-71ef-8db1-37777dc20895'::uuid,'','/4BHDmYiuSnNL3nqKIOzLJKYX4AN.jpg','तेरी मेरी डोरियाँ','TV_SERIES'),
