INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:27:11.388238+09',72844,'019bae86-d81c-73df-8d81-92a1d1091eff'::uuid,'유령을 보았던 아이들, 유령과 살았던 아이들. 이제 어른이 되었는데도, 악몽은 그들을 떠나지 않는다. 그러니, 돌아가야 한다. 아직도 선명한 그 집의 그림자를 향해.','/yD3lvZNfnaXzlkK9UG72JrwxBFW.jpg','힐 하우스의 유령','TV_SERIES'),
	 (0.0,0,'2026-01-12 04:27:11.388253+09',3213,'019bae86-d81c-741d-8d82-10326f6d0099'::uuid,'','/areZG2JxZUYjCs2oDpkf2TW1ziX.jpg','Marcus Welby, M.D.','TV_SERIES'),
