INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:27:11.393726+09',4020,'019bae86-d821-7bae-a0ce-25a989cf5a1e'::uuid,'','/1v9PXvumKXZT9AKzNjqdAADNPKS.jpg','8 Out of 10 Cats','TV_SERIES'),
