INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:27:22.115211+09',260716,'019bae87-0203-7372-b6cd-545ba3a278fa'::uuid,'','/bukUJlvSfOF6s97R4QG1fuiCRsm.jpg','無用的謊言','TV_SERIES'),
	 (0.0,0,'2026-01-12 04:27:22.115226+09',92782,'019bae87-0203-73ad-b6ce-8f73a80c6de2'::uuid,'저지시티에 사는 미국인 무슬림 가정의 10대 소녀 카말라 칸. 게임에 죽고 사는 그녀는 열렬한 팬픽션 작가이자 슈퍼 히어로 덕후로 특히 캡틴 마블에 대한 팬심은 상상을 초월한다. 그러던 어느 날, 그토록 우러러보던 슈퍼 히어로처럼 카말라에게도 슈퍼 파워가 생기는데. 지금껏 학교에서도, 때로는 집에서도 겉돌던 그녀의 인생, 이제 슈퍼 파워가 생겼으니 폼 나게 달라지려나?','/5K0F6lYosnp162drTXTJD9Pisp6.jpg','미즈 마블','TV_SERIES'),
	 (0.0,0,'2026-01-12 04:27:22.115239+09',72304,'019bae87-0203-73e5-b6cf-6c4f2caeb075'::uuid,'끝난 줄 알았던 마법사들의 성배 전쟁. 그러나 사라진 보물이 다시 나타나며 일찍이 없었던 대혈투, 이른바 ‘성배 대전’이 시작된다.','/cGfVOpsbfI08bbHV39qLqlaXsvP.jpg','페이트 / 아포크리파','TV_SERIES'),
	 (0.0,0,'2026-01-12 04:27:22.115253+09',72311,'019bae87-0203-741c-b6d0-6952194cafaa'::uuid,'조위의 참신한 시각으로 위국대군사 사마의의 파란만장한 일생과 후삼국시대를 그린 드라마','/iaEu7egJi3bBCKkDUGdsRagMKFA.jpg','사마의','TV_SERIES'),
