INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:27:32.95101+09',68157,'019bae87-2c57-703c-aa6f-e34d3a1cc6ec'::uuid,'2015년 1월 tvN에서 방영을 시작한 리얼리티쇼. 나영석 PD가 연출을 맡았다. 농촌을 벗어난 삼시세끼, 이번엔 어촌이다. 자급자족 어부 라이프를 슬로건으로 전라남도 신안군 흑산면 만재도와 전라남도 고흥군 도양읍 득량도를 오가며 정성스러운 한 끼를 찾아 떠나는출연진들의 고군분투 생존기를 그린다. 전작에 이어 환상의 케미를 자랑하는 차승원과 유해진 콤비, 이서진과 에릭, 윤균상 삼형제들과 그들을 찾아오는 게스트들이 등장하며, 전작보다 더욱 더 업그레이드된 요리들이 시청자의 눈을 현혹한다.','/tZCKvLfEsU6PVgjuHNNYACoksq0.jpg','삼시세끼 어촌편','TV_SERIES'),
	 (0.0,0,'2026-01-12 04:27:32.951025+09',127549,'019bae87-2c57-707a-aa70-a94b65632ea8'::uuid,'','/pIEUZBFYjAnqnORHIa2cSEgruLE.jpg','사사키와 미야노','TV_SERIES'),
	 (0.0,0,'2026-01-12 04:27:32.951039+09',51773,'019bae87-2c57-70b3-aa71-1b9c7fb57b5a'::uuid,'','/6oAAjh2SS4ZsTY4cF3f52K3VxVJ.jpg','Πενήντα Πενήντα (50 50)','TV_SERIES'),
	 (0.0,0,'2026-01-12 04:27:32.951053+09',70204,'019bae87-2c57-70ec-aa72-f290c0676d9a'::uuid,'''순풍산부인과'' 사람들의 일상 헤프닝을 다룬 시트콤','/cRvExNNMVinTXyW8YITQQ62oznN.jpg','순풍산부인과','TV_SERIES'),
	 (0.0,0,'2026-01-12 04:27:32.951068+09',66111,'019bae87-2c57-7129-aa73-f1169a614b93'::uuid,'서기 2067년 은하계 변방의 성계를 중심으로 자신을 잃고 광폭화하여 파괴의 최후를 맞는 바르 신드롬이 확대되고 있었다. 사태를 중요하게 본 성간복합기업체는 그 증상을 진정시키기 위해 소녀들에 의한 전술음악유닛 발퀴레와 공동작전을 수행하는 발키리 부대를 결성한다.
