INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:27:32.95948+09',247453,'019bae87-2c5f-77c0-946f-0c453fc8f4af'::uuid,'대학을 졸업한 후, 직장 동료로 다시 만난 구쉰과 웨첸링이 각각 온라인과 오프라인에서 서로를 짝사랑하게 되며 벌어지는 쌍방 삽질 로맨스','/vGAZN1QhnYX97pTdnQazPllky3j.jpg','별대아동심：날 설레게 하지마','TV_SERIES'),
