INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:27:47.710168+09',243964,'019bae87-65fe-72cf-b4eb-0f609e5ca702'::uuid,'영화에만 빠져 살던 그가 까칠한 영화감독 지망생에게 빠져버린다. 설렘 가득했던 시작과 꿈처럼 스친 만남, 그리고 갑작스러운 이별의 순간. 시간이 흘러 우연히 만난 둘에게 새로운 사랑은 피어날까.','/cQNyo6x90VMmklNEprjzOgk1ibu.jpg','멜로무비','TV_SERIES'),
