INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:27:47.719836+09',222787,'019bae87-6607-7d72-9fd5-89875c573f92'::uuid,'인간과 인조인간이 혼재하는 세계, 인조인간 소녀 루쥬는 버디 나오미와 함께 화성에서 한 임무를 맡고 있었다. 바로 ''정부에 적대하는 9명의 인조인간 살해''. 인조인간 소녀 루쥬의 치열한 이야기가 시작된다.','/1CDLkODOhSrSHYykxjYQSAPrKfM.jpg','메탈릭 루쥬','TV_SERIES'),
