INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:27:47.721847+09',106322,'019bae87-6609-7da0-b067-bae4a8159c91'::uuid,'난생처음 혼자서 심부름을 하러 가는 어린아이의 모습을 카메라에 담았다. 많은 이의 사랑을 받은 일본의 장수 리얼리티 쇼.','/4xDziU0FI5DUWySTbbzsL7iplrK.jpg','나의 첫 심부름','TV_SERIES'),
