INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:28:38.776742+09',62553,'019bae88-2d78-7bef-b327-02a3c1318003'::uuid,'튀르키예 출신 러시아 차르 군대의 군인 쿠르트 세이트는 아름다운 러시아 귀족의 딸 알렉산드라 슈라와 사랑에 빠진다. 두 사람은 제1차 세계 대전 직전 불안정한 상황 속에, 튀르키예와 러시아 국경의 경계를 뛰어넘어 이스탄불의 호텔에서 새로운 삶을 함께 시작하지만, 점점 삶의 격차를 느끼며 관계가 흔들리기 시작한다. 거기에 전쟁의 그림자가 두 사람의 사랑을 덮치는데...','/hEUJIMDvvu8K9f16AX8bZvUoG9r.jpg','세이트와 슈라','TV_SERIES'),
