INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:28:38.777531+09',74944,'019bae88-2d79-789a-aa90-785bd09555b9'::uuid,'괴물이나 귀신들의 습격에 대항하기 위해서 영력을 가진 사람들을 모아서 특수한 부대인 제국화격단의 주력인 화조는 제국 극장 지하에 본부를 두고 제도의 평화를 지키고 있었다. 평소 그들은 제국 가극단으로 연극을 펼치지만 제도를 위협하는 사악한 무리가 나타나면 제국 화격단 화조가 되어 악과 싸워나간다.
INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
