INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:28:38.779603+09',66979,'019bae88-2d7b-79b6-b933-9eb661b65b56'::uuid,'공 하나. 그것뿐인 인연. 아무 장점도 없고, 특기도 없지만, 아무도 모르게 뜨거운 열정을 품은 소년 츠카모토 츠요시. 니시도쿄의 명문 세이세키 고교 축구부에 입부 했을 때, 운명을 격렬하게 회전하기 시작한다. 고독한 축구 천재 카자마 진, 초고교급 플레이어인 주장 미즈키 히사히토, 톱 아래 군림하는 쿨한 사령탑 키미시타 아츠시, 유아독존계 대형 포워드 오오시바 키이치. 이상한 사람들이 모인 혹독하지만 다정한 부활동 속에서, 소년들은 무엇과도 바꿀 수 없는 인연을 맺기 시작한다. 이것은, 한결같이 뜨겁고, 어디까지나 순수한, 니시도쿄 축구부의 땀과 기적과 우정의 이야기.','/p2ZcAwKodFRhUiUpIvG3NgfaUOP.jpg','데이즈','TV_SERIES'),
	 (0.0,0,'2026-01-12 04:28:38.779963+09',204264,'019bae88-2d7b-7f79-b94c-30d25bf7682e'::uuid,'','/uxq6Sx3jVIvXhunmqwNzl1V7dYY.jpg','Funniest Pets & People','TV_SERIES'),
	 (0.0,0,'2026-01-12 04:28:38.779977+09',77290,'019bae88-2d7b-7fb2-b94d-8a25179dfdfa'::uuid,'대한민국 웃음의 대세 ''코미디빅리그'' 대세 ''코미디언''들의 웃음 사냥을 위한 치열한 코너 경쟁을 치르는 개그 프로그램','/cDVfraJA0rh7fHEQmkvg3ZvrBlJ.jpg','코미디빅리그','TV_SERIES'),
