INSERT INTO public.contents (average_rating,review_count,created_at,source_id,id,description,thumbnail_url,title,"type") VALUES
	 (0.0,0,'2026-01-12 04:28:56.400629+09',35168,'019bae88-7250-7a21-898f-2d0b0eb0389e'::uuid,'흥부와 놀부로 대변되는 두 형제의 가정의 중심으로 벌어지는 일상을 가벼운 코믹터치로 풀어가는 홈드라마',NULL,'흥부네 박터졌네','TV_SERIES'),
