	 (0.0,0,'2026-01-12 04:28:56.411203+09',24458,'019bae88-725b-734f-8551-422b9258e62d'::uuid,'','/dH8eCmfiYZiTmrpw412goPm7xpC.jpg','뱀부 블레이드','TV_SERIES'),
	 (0.0,0,'2026-01-12 04:28:56.411216+09',53130,'019bae88-725b-7387-8552-87ffbaa86157'::uuid,'','/oWQOI7xf4ySqe4e4qXtWnpBTigr.jpg','Knallerfrauen','TV_SERIES'),
